from nanobrain.core.step import BaseStep, StepConfig
from nanobrain.utils.yaml import load_yaml

class ThresholdStepConfig(StepConfig):
    threshold: float = 0.0

class ThresholdStep(BaseStep):
    _config_class = ThresholdStepConfig

    def __init__(self, config_path=None):
        super().__init__(config_path)
        self._threshold = self.config.threshold

    async def process(self, input_data: dict, **kwargs) -> dict:
        items = input_data.get("items", [])
        return {"above": [x for x in items if x > self._threshold]}

@BaseStep.register
class ThresholdStepLoader(BaseStep.Loader):
    async def load(self, yaml_path: str) -> ThresholdStep:
        config = load_yaml(yaml_path)
        step_config = ThresholdStepConfig(**config.get("step", {}))
        return ThresholdStep(config=step_config)

from nanobrain.core.step import BaseStep
import yaml

class ConcatStep(BaseStep):
    async def process(self, input_data: dict, **kwargs) -> dict:
        parts = input_data.get("parts", [])
        sep = input_data.get("sep", "")

        if not isinstance(sep, str):
            sep = ""

        joined = sep.join(parts)
        return {"joined": joined}

    @classmethod
    def from_config(cls, yaml_path: str) -> 'ConcatStep':
        with open(yaml_path, 'r') as f:
            config = yaml.safe_load(f)

        step = cls(**config)
        return step

from nanobrain.core.step import BaseStep
from typing import Dict, List

class DedupePreserveOrderStep(BaseStep):
    async def process(self, input_data: Dict[str, List], **kwargs) -> Dict[str, List]:
        seen = set()
        unique_items = []
        for item in input_data["items"]:
            if item not in seen:
                seen.add(item)
                unique_items.append(item)
        return {"unique": unique_items}

from nanobrain.core.step import BaseStep
