class DoubleStep(BaseStep):
    async def process(self, input_data: dict, **kwargs) -> dict:
        if not isinstance(input_data, dict) or 'n' not in input_data or not isinstance(input_data['n'], int):
            return {"error": "Invalid input. Expected {'n': int}"}
        doubled = input_data['n'] * 2
        return {"doubled": doubled}

    @classmethod
    def from_config(cls, yaml_path: str) -> 'DoubleStep':
        with open(yaml_path, 'r') as f:
            config = yaml.safe_load(f)
        return cls(**config)

