from nanobrain.core.step import BaseStep
import yaml

class UpperStep(BaseStep):
    async def process(self, input_data: dict, **kwargs) -> dict:
        if 'text' not in input_data or not isinstance(input_data['text'], str):
            return {"output": ""}
        return {"output": input_data['text'].upper()}

UpperStep.from_config = lambda self, yaml_path: UpperStep(yaml.safe_load(open(yaml_path)))

from nanobrain.core.step import BaseStep
import yaml

class WordCountStep(BaseStep):
    @classmethod
    def from_config(cls, yaml_path):
        with open(yaml_path) as f:
            config = yaml.safe_load(f)
        return cls(**config)

    async def process(self, input_data: dict, **kwargs) -> dict:
        text = input_data.get("text", "")
        count = len(text.split())
        return {"count": count}
